namespace CastleFight {
public sealed partial class HumanMatch {
    public sealed class ElementalJob {public string kind;public Unit source;public int team,nova;public Vector2 point;public float left,angle,power;}
    public sealed class ElementalZone {public int id,team,pulses;public string ability;public Vector2 point;public float timer,interval;}
    public sealed class ElementalProjectile {public int id,team,forks,turn,lastVictim=-1,nova;public bool last;public Vector2 point,previous;public float angle,power,remaining;}
    public sealed class ElementalWave {public int id,team;public Vector2 origin,direction;public float distance;public readonly HashSet<int> struck=new HashSet<int>();}
    public readonly List<ElementalWave> ElementalWaves=new List<ElementalWave>();
    public readonly List<ElementalJob> ElementalJobs=new List<ElementalJob>();
    public readonly List<ElementalZone> ElementalZones=new List<ElementalZone>();
    public readonly List<ElementalProjectile> ElementalRays=new List<ElementalProjectile>(),ElementalSpheres=new List<ElementalProjectile>();
    float elementalClock;public int ElementalSplits,ElementalMirrors,ElementalBursts,ElementalDetonations;
    bool ElementalEligible(Unit u,int team)=>u!=null&&u.hp>0&&u.team==team&&((string)Lines[u.kind].stats["unit_types"]??"").ToLowerInvariant().Contains("sapper");
    bool ElementalIllusion(Unit u)=>u.elementalIllusion||(bool?)Lines[u.kind].stats["illusion"]==true;
    public int[] ElementalCounts(int team){var counts=new int[6];foreach(var h in Huts)if(h.hp>0&&h.paid&&h.team==team){int element=(int?)elementalBuildings[Lines[h.kind].building]??0;if(element>0)counts[element]++;}return counts;}
    public float ElementalManaBonus(Hut hut){if(StatMaxMana033(hut.kind)<=0)return 0;if(ElementalLinkNearby033(hut.team,hut.position))return F(Abilities["A0EL"]?["ranks"]?[Lines[hut.kind].abilities.Contains("A0DS")?1:0]?["fields"],"Arm1");for(int i=0;i<Huts.Count;i++){var h=Huts[i];if(h.team!=hut.team||!h.paid||h.hp<=0)continue;if(!HasLink033(h.kind))continue;if(BuildingDisabled(h)>0)continue;float rr=F(Abilities["A0EL"]?["fields"],"aare",0)/30;if((h.position-hut.position).sqrMagnitude<=rr*rr)return F(Abilities["A0EL"]?["ranks"]?[Lines[hut.kind].abilities.Contains("A0DS")?1:0]?["fields"],"Arm1");}return 0;}
    Unit[] ElementalTargets(int team,Vector2 at,JToken cfg){string kind=(string)cfg["kind"];var targets=Units.Where(u=>kind=="elemental_enchant"?ElementalEligible(u,team):ElementalEligible(u,1-team)&&(kind=="elemental_barrage"?Valid(u,team,cfg,false)&&!IsNagaHero(u)&&Vector2.Distance(at,u.position)<=F(cfg,"range"):(string)cfg["id"]=="A0FG"?Flying(u):!Flying(u)&&!Invulnerable(u)&&!u.abilities.Contains("A08H"))).ToArray();if(kind=="elemental_enchant"&&targets.Any(u=>!u.abilities.Contains("A0F4")))targets=targets.Where(u=>!u.abilities.Contains("A0F4")).ToArray();return targets;}
    public void ElementalEnchant(Unit target,string forced=null){if(target.maxHp-target.hp>350){Heal(target,450);return;}var options=new[]{"A0D7","A0F3","A0F1"}.Where(id=>!target.abilities.Contains(id)).ToArray();if(options.Length==0){Heal(target,450);return;}string chosen=forced??options[Mathf.Min(options.Length-1,(int)(Roll()*options.Length))];Grant(target,chosen);Grant(target,"A0F4");if(chosen=="A0F1")Grant(target,"A03Q");PulseAt(target.position,1,Color.cyan,"Зачарование",1,"elemental:elemental_enchant_target:effect");}
    bool CastElementalUnit(Unit source,JToken cfg,Unit suggested){var targets=ElementalTargets(source.team,source.position,cfg);if(targets.Length==0)return false;ElementalBarrage(source,Roll()<.5f);return true;}
    public bool CastElementalBuilding(Hut h,string id,int suggested=-1){var cfg=Abilities[id];if(h==null||!Huts.Contains(h)||!h.paid||h.hp<=0||h.paused||BuildingDisabled(h)>0||cfg==null||!Lines[h.kind].abilities.Contains(id)||h.mana<F(cfg,"mana")||h.spellTimers.TryGetValue(id,out float wait)&&wait>0)return false;var targets=ElementalTargets(h.team,h.position,cfg);if(targets.Length==0)return false;var target=targets.FirstOrDefault(u=>u.id==suggested)??targets[Mathf.Min(targets.Length-1,(int)(Roll()*targets.Length))];if((string)cfg["kind"]=="elemental_enchant"){ElementalEnchant(target);PulseAt(h.position,1,Color.cyan,"",1,"elemental:elemental_enchant_caster:effect");}else if((string)cfg["kind"]=="elemental_rain")StartElementalRain(h.team,target.position,id=="A0FG"?"A0D0":Roll()<.5f?"A0D1":"A0E3");else return false;h.mana-=F(cfg,"mana");h.spellTimers[id]=BuildingCooldown(h,F(cfg,"cd"));h.attackSerial++;h.attackPoseLeft=.5f;SpellsCast++;return true;}
    void TickElementalBuilding(Hut h){foreach(string id in Lines[h.kind].abilities)if(new[]{"elemental_enchant","elemental_rain"}.Contains((string)Abilities[id]?["kind"])&&(!h.spellTimers.TryGetValue(id,out float wait)||wait<=0))h.spellTimers[id]=CastElementalBuilding(h,id)?BuildingCooldown(h,F(Abilities[id],"cd")):.25f;}
    // User override: primordial fire/water produce only their main fighter.
    // Keep the read-only Godot catalog and existing model identities for audits.
    public static bool RemovedElementalCompanion(string raw)=>raw=="h0DC"||raw=="h0DB";
    public string[] ProductionRoster(Line line)=>(line.production??Array.Empty<string>()).Where(raw=>!RemovedElementalCompanion(raw)).ToArray();
    void ElementalCreated(Unit u,bool production){if(!production||Lines[u.kind].unit!="h030")return;u.elementalLavaGeneration=1;u.pose="Birth";u.castPause=.3f;}
    public void ElementalAfterWeapon(Unit source,float actual){if(source==null||source.hp<=0||ElementalIllusion(source)||actual<=0||source.elementalLavaGeneration<=0||source.elementalLavaGeneration>=3||source.elementalLavaPending)return;if(++source.elementalLavaHits<15)return;source.elementalLavaPending=true;ElementalJobs.Add(new ElementalJob{kind="lava",source=source,left=2});}
    void ElementalMirror(Unit source,int roll=-1){if(source.hp<=0||source.elementalMirrorCd>0||source.elementalMirrorPending||(roll<0?(int)(Roll()*100):roll)>=20)return;source.elementalMirrorCd=3;source.elementalMirrorPending=true;source.castPause=Mathf.Max(source.castPause,.5f);ElementalJobs.Add(new ElementalJob{kind="mirror",source=source,left=.5f});}
    void ElementalForged(Unit source,Vector2 point,float actual){foreach(var u in Units.ToArray())if(ElementalEligible(u,1-source.team)&&!Invulnerable(u)&&Vector2.Distance(u.position,point)<=250f/30&&Lines[source.kind].weapons.Any(w=>Flying(u)?w.air:w.ground))DamageUnit(u,actual*.5f,source.team,"chaos",true,false,null,false,true);}
    void ElementalAfterDamage(Unit source,Unit victim,float actual,bool suppress=false){if(actual<=0||suppress)return;if(source!=null&&!ElementalIllusion(source)&&source.abilities.Contains("A03Q")){if(source.abilities.Contains("A0F1"))ElementalForged(source,victim.position,actual);if(source.abilities.Contains("A0DW")&&source.hp>0&&victim.hp>0)DamageUnit(victim,50*F(Lines[source.kind].stats,"level",1)*source.hp/Mathf.Max(1,source.maxHp),source.team,"siege",true,false,source,false,true,0,true);if(Lines[source.kind].unit=="h02Y")ElementalMirror(source);}if(victim.hp>0&&!ElementalIllusion(victim)){if(victim.abilities.Contains("A0DX")&&source!=null&&source.hp>0&&(source.pendingWeapon??WeaponFor(source,victim))?.type=="normal")ElementalRetaliate(source,victim);if(Lines[victim.kind].unit=="o00E"&&!victim.elementalArmed){victim.mana+=actual;if(victim.mana>=680){victim.elementalArmed=true;victim.abilities.Remove("A0C5");Grant(victim,"A0EN");}}}}
    void ElementalTowerHit(int owner,int team,Unit victim,float actual){if(actual<=0||victim.hp<=0)return;var h=Huts.FirstOrDefault(v=>v.id==owner&&v.hp>0);if(h!=null&&Lines[h.kind].building=="h061"&&(int)(Roll()*100)<40)ElementalDummyMissile(team,h.position,victim,Abilities["A0DC"]);}
    public bool ElementalRetaliate(Unit attacker,Unit victim,int roll=-1){if((attacker.pendingWeapon??WeaponFor(attacker,victim))?.type!="normal")return false;int rank=Mathf.Clamp((int)F(Lines[victim.kind].stats,"level",1),1,2);if((roll<0?(int)(Roll()*100):roll)>15*rank)return false;ElementalDummyMissile(victim.team,victim.position,attacker,Abilities["A0D5"]["ranks"][rank-1]);return true;}
    public void ElementalDummyMissile(int team,Vector2 at,Unit target,JToken cfg){if(!Valid(target,team,cfg,false))return;var f=cfg["fields"];var w=new Weapon{type="missile",missile="elemental:"+(string)cfg["id"],speed=F(f,"amsp",1000)/30,arc=F(f,"amac"),homing=true};var shot=AddShot(team,target.kind,-1,target.id,at,target.position,F(cfg,"power"),w,F(cfg,"stun"),3);shot.chaosSpell="elemental_dummy";shot.elementalConfig=(JObject)cfg.DeepClone();}
    bool ImpactElementalShot(Shot shot){if(shot.chaosSpell!="elemental_dummy")return false;var target=FindUnit(shot.target);if(Valid(target,shot.team,shot.elementalConfig,false)&&!NagaShieldBlock(target)){DamageUnit(target,shot.damage,shot.team);if(target.hp>0){float duration=F(shot.elementalConfig,IsNagaHero(target)?"hero_duration":"duration");target.stun=Mathf.Max(target.stun,duration);PulseAt(target.position,1,Color.cyan,"Оглушение",duration,"elemental:"+(string)shot.elementalConfig["id"]+":target");}}return true;}
    bool ElementalOrb(Unit source,Unit target,JToken cfg){if((string)cfg?["id"]=="A0CN"){if(Valid(target,source.team,cfg,false)){var direction=target.position-source.position;ElementalWaves.Add(new ElementalWave{id=nextId++,team=source.team,origin=source.position,direction=direction.sqrMagnitude>.001f?direction.normalized:source.direction});}return true;}if((string)cfg?["kind"]!="elemental_fork")return false;if(!Valid(target,source.team,cfg,false)||((string)cfg["targets"]??"").Contains("structure"))return true;var victims=new[]{target}.Concat(Units.Where(u=>u!=target&&Valid(u,source.team,cfg,false)&&Vector2.Distance(u.position,target.position)<=F(cfg,"area"))).Take((int)F(cfg,"count",1)).ToArray();foreach(var u in victims){DamageUnit(u,F(cfg,"power"),source.team);ElementalLightning(source.team,source.position,u.position);}return true;}
    void ElementalLightning(int team,Vector2 at,Vector2 end){PulseAt(end,1,Color.cyan,"",.3f,"elemental:elemental_bolt_hit:effect");var w=new Weapon{type="instant",missile="elemental_fork",attack="magic"};AddShot(team,0,-1,-1,at,end,0,w,0,1);}
    void ElementalStructureHit(Unit source,int target,float actual){if(source==null||source.hp<=0||ElementalIllusion(source)||actual<=0)return;ElementalAfterWeapon(source,actual);var hut=FindHut(target);Vector2 center=target==-1?new Vector2(CastlePosition(1-source.team).x,0):hut?.position??TargetPosition(target,source.team);if(source.abilities.Contains("A03Q")){if(source.abilities.Contains("A0F1"))ElementalForged(source,center,actual);if(source.abilities.Contains("A0DW")){float power=50*F(Lines[source.kind].stats,"level",1)*source.hp/Mathf.Max(1,source.maxHp);if(target==-1)CastleHp[1-source.team]=Mathf.Max(0,CastleHp[1-source.team]-power*Multiplier("siege",CastleArmorType));else DamageHut(hut,power,"siege",source.team,true,true);}if(Lines[source.kind].unit=="h02Y")ElementalMirror(source);}foreach(string id in new[]{"A0F7","A0F0"})if(source.abilities.Contains(id)&&Roll()<F(Abilities[id],"chance")){var cfg=Abilities[(string)Abilities[id]["effect"]];if(target==-1)DamageCastle(1-source.team,F(cfg,"power"),"magic",true);else DamageHut(hut,F(cfg,"power"),"magic",source.team,true);ElementalLightning(source.team,source.position,center);}}
    void ElementalDied(Unit victim,Unit killer,int team){ElementalResonanceDeath(victim);if(victim.elementalArmed)ElementalDetonate(victim);if(killer==null&&team<0)return;if(ElementalIllusion(victim)||victim.summoned||victim.abilities.Contains("A07G")||victim.abilities.Contains("A07H")||!victim.abilities.Contains("A0F5"))return;if(Huts.Any(h=>h.team==victim.team&&h.hp>0&&h.paid&&Lines[h.kind].building=="h063")){float amount=Mathf.Min(400,20*ElementalCounts(victim.team).Sum());foreach(var ally in Units.Where(u=>ElementalEligible(u,victim.team)&&Vector2.Distance(u.position,victim.position)<=512f/30)){Heal(ally,amount*(Lines[ally.kind].unit==Lines[victim.kind].unit?1:.3f));PulseAt(ally.position,1,Color.green,"",1,"elemental:elemental_link_heal:effect");}}}
    void ElementalResonanceDeath(Unit victim){if(!TeamElemental[victim.team]||Aspects[victim.team]!=0||ElementalIllusion(victim)||Invulnerable(victim)||Hidden(victim)||victim.summoned||victim.spellBorn||victim.noBounty)return;foreach(var ally in Units.Where(u=>ElementalEligible(u,victim.team)&&!ElementalIllusion(u)&&Lines[u.kind].unit==Lines[victim.kind].unit&&u.elementalResonanceCd<=0&&Vector2.Distance(u.position,victim.position)<=600f/30).OrderBy(u=>(u.position-victim.position).sqrMagnitude).Take(4)){Heal(ally,ally.maxHp*.1f);ally.elementalResonanceCd=3;PulseAt(ally.position,1,Color.green,"Резонанс",1,"elemental:elemental_resonance:trigger");}}

    public void ElementalDetonate(Unit source){if(source.elementalDetonated)return;source.elementalDetonated=true;ElementalDetonations++;var f=Abilities["A0EN"]["fields"];foreach(var u in Units.ToArray())if(ElementalEligible(u,1-source.team)&&Flying(u)){float d=Vector2.Distance(u.position,source.position)*30;if(d<=F(f,"Dda3"))DamageUnit(u,F(f,d<=F(f,"Dda1")?"Dda2":"Dda4"),source.team);}foreach(var h in Huts.ToArray())if(h.team!=source.team&&h.hp>0&&h.paid){float d=Vector2.Distance(h.position,source.position)*30;if(d<=F(f,"Dda3"))DamageHut(h,F(f,d<=F(f,"Dda1")?"Dda2":"Dda4")*F(f,"Sds1"),"magic",source.team,true);}float castle=Vector2.Distance(source.position,new Vector2(CastlePosition(1-source.team).x,0))*30;if(castle<=F(f,"Dda3"))DamageCastle(1-source.team,F(f,castle<=F(f,"Dda1")?"Dda2":"Dda4")*F(f,"Sds1"),"magic",true);PulseAt(source.position,350f/30,Color.cyan,"",1,"elemental:elemental_wind_blast:effect");}
    bool TickElementalWind(Unit u,float dt){if(!u.elementalArmed)return false;u.pendingSpell=null;u.strikeLeft=u.castLeft=-1;u.combatTarget=-1;var destination=new Vector2(CastlePosition(1-u.team).x,0);float closest=Vector2.Distance(u.position,destination);foreach(var enemy in Units)if(ElementalEligible(enemy,1-u.team)&&Flying(enemy)&&!Invulnerable(enemy)&&Vector2.Distance(u.position,enemy.position)<closest){closest=Vector2.Distance(u.position,enemy.position);destination=enemy.position;}foreach(var h in Huts)if(h.team!=u.team&&h.paid&&h.hp>0&&Vector2.Distance(u.position,h.position)<closest){closest=Vector2.Distance(u.position,h.position);destination=h.position;}u.direction=(destination-u.position).normalized;u.position=Vector2.MoveTowards(u.position,destination,15*dt);u.pose="Walk";return true;}
    public void StartElementalRain(int team,Vector2 point,string id){var cfg=Abilities[id];var f=cfg["fields"];float interval=F(f,id=="A0E3"?"Esf2":"Hbz4");int pulses=id=="A0E3"?Mathf.RoundToInt(F(f,"adur")/interval):(int)F(f,"Hbz1");ElementalZones.Add(new ElementalZone{id=nextId++,team=team,point=point,ability=id,interval=interval,timer=interval,pulses=pulses});PulseAt(point,F(cfg,"area"),Color.cyan,"",interval*pulses,"elemental:elemental_rain_"+id+":effect");}
    void ElementalRainPulse(ElementalZone zone){var cfg=Abilities[zone.ability];float power=F(cfg["fields"],zone.ability=="A0E3"?"Esf1":"Hbz2");foreach(var u in Units.ToArray())if(Valid(u,zone.team,cfg,false)&&Vector2.Distance(u.position,zone.point)<=F(cfg,"area")){DamageUnit(u,power,zone.team);if(zone.ability=="A0D0"&&u.hp>0)ApplyEffectData(u,new JObject{["id"]="A0D0",["name"]="Горение",["kind"]="debuff",["duration"]=3,["dps"]=F(cfg["fields"],"Hbz5")},zone.team);}if(zone.ability=="A0D1"){foreach(var h in Huts.ToArray())if(h.team!=zone.team&&h.paid&&h.hp>0&&Vector2.Distance(h.position,zone.point)<=F(cfg,"area"))DamageHut(h,power,"magic",zone.team,true);if(Vector2.Distance(new Vector2(CastlePosition(1-zone.team).x,0),zone.point)<=F(cfg,"area"))DamageCastle(1-zone.team,power,"magic",true);}}
    public void ElementalBarrage(Unit source,bool lightning){var c=ElementalCounts(source.team);float heading=Mathf.Atan2(source.direction.y,source.direction.x);if(lightning){int lanes=2+c[3]/3;var direction=new Vector2(Mathf.Cos(heading),Mathf.Sin(heading));float lateral=-50*(lanes/2)+50*((lanes+1)%2)/2f;for(int i=0;i<lanes;i++)AddElementalRay(source.team,source.position+direction+new Vector2(-direction.y,direction.x)*(lateral+i*50)/30,heading,2+c[5]/2,75*Mathf.Min(1+c[1],4),i==lanes-1);}else for(int i=0;i<5+c[4]*2;i++)ElementalJobs.Add(new ElementalJob{kind="sphere",team=source.team,point=source.position,angle=heading+(Roll()*90-45)*Mathf.Deg2Rad,power=75*Mathf.Min(1+c[2],4),nova=Mathf.Clamp(c[5]/4,1,3),left=i*.04f});source.elementalPose=lightning?"Spell Slam":"Spell Throw";source.elementalPoseLeft=.7f;}
    public ElementalProjectile AddElementalRay(int team,Vector2 at,float angle,int forks,float power,bool last){var ray=new ElementalProjectile{id=nextId++,team=team,point=at,previous=at,angle=angle,forks=forks,power=power,last=last,remaining=400};ElementalRays.Add(ray);return ray;}
    public void LaunchElementalSphere(int team,Vector2 at,float angle,float power,int nova){ElementalSpheres.Add(new ElementalProjectile{id=nextId++,team=team,point=at,previous=at,angle=angle,power=power,nova=nova,remaining=500});}
    Unit ElementalContact(ElementalProjectile p)=>Units.FirstOrDefault(u=>u.id!=p.lastVictim&&ElementalEligible(u,1-p.team)&&Vector2.Distance(p.point,u.position)<=34f/30);
    void AdvanceElemental(ElementalProjectile p,float distance){p.previous=p.point;p.point+=new Vector2(Mathf.Cos(p.angle),Mathf.Sin(p.angle))*distance/30;p.remaining-=distance;}
    static void RemoveElemental(List<ElementalProjectile> list,int i){list[i]=list[list.Count-1];list.RemoveAt(list.Count-1);}
    void ElementalDirect(Unit victim,float amount,int team){DamageUnit(victim,amount,team,"magic",true,false,null,false,true,0,false,"magic",true);}
    void StepElementalProjectiles(){int i=0;while(i<ElementalRays.Count){var ray=ElementalRays[i];AdvanceElemental(ray,20);var victim=ElementalContact(ray);if(victim!=null){ElementalDirect(victim,ray.power,ray.team);ray.lastVictim=victim.id;PulseAt(victim.position,1,Color.cyan,"",.4f,"elemental:elemental_bolt_hit:effect");}if(ray.remaining>0){i++;continue;}if(ray.turn==0){if(ray.forks<=0){RemoveElemental(ElementalRays,i);continue;}float angle=ray.angle;ray.angle=angle-30*Mathf.Deg2Rad;ray.forks--;ray.turn=1;ray.remaining=50;var child=AddElementalRay(ray.team,ray.point,angle+30*Mathf.Deg2Rad,ray.forks,ray.power,false);child.turn=-1;child.remaining=50;}else if(ray.turn>0&&!ray.last)RemoveElemental(ElementalRays,i);else{ray.angle+=ray.turn*30*Mathf.Deg2Rad;ray.turn=0;ray.remaining=400;}}
        i=0;while(i<ElementalSpheres.Count){var sphere=ElementalSpheres[i];AdvanceElemental(sphere,26);var victim=ElementalContact(sphere);if(victim!=null){ElementalDirect(victim,sphere.power,sphere.team);if(victim.hp>0&&Valid(victim,sphere.team,Abilities["A043"],false)&&!NagaShieldBlock(victim)){var cfg=Abilities["A043"];foreach(var u in Units.ToArray())if(Valid(u,sphere.team,cfg,false)&&Vector2.Distance(u.position,victim.position)<=F(cfg,"area")){DamageUnit(u,F(cfg,u==victim?"power":"secondary"),sphere.team);if(u.hp>0){var slow=(JObject)cfg.DeepClone();slow["power"]=0;ApplyEffectData(u,slow,sphere.team);}}PulseAt(victim.position,3,Color.cyan,"",1,"elemental:A043:effect");}}if(victim!=null||sphere.remaining<=0)RemoveElemental(ElementalSpheres,i);else i++;}
    }
    bool ElementalStormReleased(Unit source,int target){if(!TeamElemental[source.team]||Aspects[source.team]!=1||!ElementalEligible(source,source.team)||ElementalIllusion(source)||!ElementalEligible(FindUnit(target),1-source.team))return false;return ++source.elementalStormAttacks%4==0;}
    void ElementalStormBurst(int team,Vector2 point,int primary,Unit source=null){if(source!=null&&source.team!=team)source=null;ElementalBursts++;foreach(var u in Units.Where(u=>ElementalEligible(u,1-team)&&!Invulnerable(u)&&!Hidden(u)&&Vector2.Distance(u.position,point)<=300f/30).OrderBy(u=>u.id==primary?0:1).ThenBy(u=>(u.position-point).sqrMagnitude).Take(3).ToArray())DamageUnit(u,45,team,"magic",true,false,source);PulseAt(point,3,Color.cyan,"Стихийная буря",.8f,"elemental:elemental_storm:trigger");}
    void TickElemental(float dt){foreach(var u in Units){u.elementalMirrorCd=Mathf.Max(0,u.elementalMirrorCd-dt);u.elementalResonanceCd=Mathf.Max(0,u.elementalResonanceCd-dt);u.elementalPoseLeft=Mathf.Max(0,u.elementalPoseLeft-dt);}foreach(var u in Units.ToArray())if(u.hp>0&&u.elementalArmed&&u.stun<=0&&!Disabled(u)&&Units.Any(v=>ElementalEligible(v,1-u.team)&&Flying(v)&&Vector2.Distance(v.position,u.position)<=250f/30)||u.hp>0&&u.elementalArmed&&u.stun<=0&&!Disabled(u)&&(Huts.Any(h=>h.paid&&h.hp>0&&h.team!=u.team&&Vector2.Distance(h.position,u.position)<=250f/30)||Vector2.Distance(u.position,new Vector2(CastlePosition(1-u.team).x,0))<=250f/30)){ElementalDetonate(u);DamageUnit(u,u.hp+1,-1,"chaos",true,false,null,false,true);}
        var waveCfg=Abilities["A0CN"];foreach(var wave in ElementalWaves.ToArray()){float previous=wave.distance;wave.distance=Mathf.Min(F(waveCfg,"wave_length"),wave.distance+F(waveCfg,"missile_speed")*dt);foreach(var target in Units.ToArray())if(!wave.struck.Contains(target.id)&&Valid(target,wave.team,waveCfg,false)){var offset=target.position-wave.origin;float along=Vector2.Dot(offset,wave.direction);float width=Mathf.Lerp(F(waveCfg,"start_width"),F(waveCfg,"end_width"),Mathf.Clamp01(along/F(waveCfg,"wave_length")));if(CorruptedTouches(offset,wave.direction,previous,wave.distance,F(Lines[target.kind].stats,"collision"),width)){wave.struck.Add(target.id);DamageUnit(target,F(waveCfg,"power"),wave.team);}}if(wave.distance>=F(waveCfg,"wave_length"))ElementalWaves.Remove(wave);}
        foreach(var job in ElementalJobs.ToArray())if((job.left-=dt)<=.000001f){ElementalJobs.Remove(job);if(job.kind=="sphere"){LaunchElementalSphere(job.team,job.point,job.angle,job.power,job.nova);continue;}var source=job.source;if(source==null||source.hp<=0)continue;if(job.kind=="mirror"){source.elementalMirrorPending=false;var clone=Spawn(source.team,source.kind,source.position+Vector2.right);clone.summoned=true;clone.noBounty=true;clone.summonLeft=60;clone.elementalIllusion=true;clone.onRoad=true;clone.leaveCastleLane=false;clone.maxHp=source.maxHp;clone.hp=source.hp;clone.armor=source.armor;clone.abilities.Clear();clone.abilityLevels.Clear();clone.critChance=clone.evasion=clone.spellResist=0;clone.elementalWeapons=Lines[source.kind].weapons.Select(w=>{var c=w.Copy();c.damage*=.6f;return c;}).ToArray();clone.effects.Add(new Effect{id="elemental_illusion",group="elemental_illusion",left=60,lifetime=60,incoming=1,config=new JObject()});ElementalMirrors++;}else if(job.kind=="lava"){source.elementalLavaPending=false;source.elementalLavaHits=0;source.elementalLavaGeneration++;Heal(source,(source.maxHp-source.hp)*.5f);var child=Spawn(source.team,Array.FindIndex(Lines,l=>l.unit=="h02Z"),source.position+Vector2.up*1.5f);child.onRoad=true;child.leaveCastleLane=false;child.pose="Birth";child.castPause=.3f;child.summoned=false;child.spellBorn=true;source.pose="Birth";ElementalSplits++;}}
        foreach(var zone in ElementalZones.ToArray()){zone.timer-=dt;while(zone.timer<=0&&zone.pulses>0){zone.timer+=zone.interval;zone.pulses--;ElementalRainPulse(zone);}if(zone.pulses<=0)ElementalZones.Remove(zone);}elementalClock+=dt;while(elementalClock>=.03f){elementalClock-=.03f;StepElementalProjectiles();}
    }
}
